/** Six dedicated sheet views; lifecycle management is a separate permission-aware destination. */
public final class CharacterDashboardScreen extends ManagementScreen {
    private final DashboardSource source;
    private DashboardModel.Tab tab=DashboardModel.Tab.SHEET,displayed=tab;
    private JsonObject character,active=new JsonObject(),encounter=new JsonObject();
    private String campaignName="",campaign="",inventorySelection="";
    private int spellLevel=-1;
    private CharacterCanvas primary;
    private CurrencyDraft money;
    private SectionRail rail;
    private RpgButton manageButton;
    private net.minecraft.client.gui.widget.TextFieldWidget filterInput;
    private final List<RpgButton> inventoryControls=new ArrayList<>();
    private final Map<DashboardModel.Tab,Integer> positions=new EnumMap<>(DashboardModel.Tab.class);
    private final Map<DashboardModel.Tab,String> focus=new EnumMap<>(DashboardModel.Tab.class);
    public CharacterDashboardScreen(Screen parent,DashboardSource source){super("Character Dashboard",parent);this.source=source;}
    public static CharacterDashboardScreen library(Screen parent,String id){return new CharacterDashboardScreen(parent,new DashboardSource(true,id));}
    public static CharacterDashboardScreen campaign(Screen parent,String id){return new CharacterDashboardScreen(parent,new DashboardSource(false,id));}
    @Override protected int maximumWidth(){return 980;}
    @Override protected UiLayout.Rect listBounds(){return DashboardLayout.shell(frame).content();}
    @Override protected void searchControls(){filterInput=search(frame.x()+84,frame.y()+frame.height()-30,Math.max(40,frame.width()-182),query,q->{query=q;if(tab==DashboardModel.Tab.INVENTORY)display();else filter();});button("Refresh","",frame.x()+frame.width()-86,frame.y()+8,74,20,this::refresh);}
    @Override protected void controls(){var r=DashboardLayout.shell(frame).rail();rail=addDrawableChild(new SectionRail(DashboardLayout.navigation(frame),Arrays.stream(DashboardModel.Tab.values()).map(t->new SectionRail.Item(t.name(),DashboardModel.title(t))).toList(),v->show(DashboardModel.Tab.valueOf(v)),28));manageButton=button("Manage Character","",r.x(),r.y()+r.height()-22,r.width(),20,()->{if(fresh&&!busy&&character!=null&&(money==null||!money.dirty()))client.setScreen(PlayerNavigation.manage(this,source));}).hint("Edit or manage this character");manageButton.active=false;}
    boolean matches(DashboardSource other){return source.library()==other.library()&&source.character().equals(other.character());}
    @Override public void tick(){super.tick();if(manageButton!=null){manageButton.active=fresh&&!busy&&character!=null&&(money==null||!money.dirty());manageButton.hint(money!=null&&money.dirty()?"Save currency before managing this character":!fresh||busy?"Wait for the character to load, or Refresh":"Edit or manage this "+(source.library()?"personal character":"campaign character"));}}
    @Override protected void refresh(){if(busy)return;fresh=false;clearRows();if(source.library())read(source.read(),source.readArgs(),data->{character=SnapshotReplies.checked(source,data);active=new JsonObject();encounter=new JsonObject();campaign="";campaignName="";display();});else read(ACTIVE,args(),a->{active=a;read(source.read(),source.readArgs(),data->{character=SnapshotReplies.checked(source,data);campaign=text(data,"campaign");read(CAMPAIGN_GET,args("campaign",campaign),c->{campaignName=text(c,"name");var id=dev.tacticalcombat.client.ClientSrdCombat.hudEncounter();if(id!=null&&selected())read(INITIATIVE,args("encounter",id),d->{encounter=d;display();});else{encounter=new JsonObject();display();}});});});}
    private boolean combat(){return flag(active,"inCombat");}
    private boolean selected(){return source.character().equals(text(active,"character"))||source.character().equals(text(active,"boundCharacter"));}
    private boolean editable(){return character!=null&&DashboardModel.editable(character,source.library(),self(),combat());}
    private void show(DashboardModel.Tab next){if(money!=null&&money.dirty()){message="Save the inline currency values before changing pages.";return;}tab=next;query="";if(filterInput!=null)filterInput.setText("");display();}
    private void remember(){if(primary!=null){positions.put(displayed,primary.position());focus.put(displayed,primary.focusedKey());}}
    private void display(){if(character==null)return;if(money==null)money=new CurrencyDraft(section("inventory"));else money.accept(section("inventory"),null);remember();if(primary!=null){remove(primary);primary=null;}inventoryControls.forEach(this::remove);inventoryControls.clear();displayed=tab;clearRows();rail.selected(tab.name());boolean listView=tab==DashboardModel.Tab.FEATURES||tab==DashboardModel.Tab.SPELLS||tab==DashboardModel.Tab.INVENTORY;list.visible=listView;filterInput.visible=listView;filterInput.setDimensionsAndPosition(Math.max(40,frame.width()-182),20,frame.x()+84,frame.y()+frame.height()-30);var body=listBounds();list.setDimensionsAndPosition(body.width(),body.height(),body.x(),body.y());
        if(tab==DashboardModel.Tab.INVENTORY){inventory();return;}
        if(!listView){primary=addDrawableChild(new CharacterCanvas(body));switch(tab){case SHEET->CharacterSheetUi.build(primary,character,source.library(),sheetActions(),null,encounter);case SKILLS->skills();case BACKGROUND->background();default->{}}primary.position(positions.getOrDefault(tab,0));String key=focus.getOrDefault(tab,"");if(!key.isEmpty()){primary.focus(key);setInitialFocus(primary);}return;}
        if(tab==DashboardModel.Tab.FEATURES)features();else spells();filter();}
    @Override protected void filter(){if(tab==DashboardModel.Tab.INVENTORY){if(list!=null)list.rows(List.copyOf(rows));}else super.filter();}
    private void inspect(FeatureReference.Entry entry){client.setScreen(new FeatureInspectScreen(this,entry));}
    private CharacterSheetUi.Actions sheetActions(){return new CharacterSheetUi.Actions(){public boolean healthEditable(){return source.library()&&editable()&&text(character,"profile").equals("srd_5_1");}public boolean trackable(String section){return CharacterDashboardScreen.this.trackable(section);}public void health(String key,int delta){CharacterDashboardScreen.this.health(key,delta);}public void track(RpgRecords.Change change){manual(change);}public void inspect(FeatureReference.Entry entry){CharacterDashboardScreen.this.inspect(entry);}public void encounters(){client.setScreen(new DestinationScreen(CharacterDashboardScreen.this,DestinationScreen.Destination.ENCOUNTERS));}public boolean campaign(){return !source.library();}public boolean inspirationAwardable(){return source.library()||flag(character,"manager");}public void resources(){if(fresh&&!busy)client.setScreen(new SheetTrackersScreen(CharacterDashboardScreen.this,character,source));}};}
    private void health(String key,int delta){if(busy||!fresh||!source.library()||!editable())return;try{var data=SrdAuthoring.data(character.getAsJsonObject("sheet"));int current=data.get(key).getAsInt(),max=key.equals("hp")?data.get("hp_max").getAsInt():1024;data.addProperty(key,(int)Math.clamp((long)current+delta,0L,(long)max));mutate(source.edit(),source.sectionArgs(character,"combat",data),next->{character=SnapshotReplies.checked(source,next);display();});}catch(RuntimeException invalid){message=invalid.getMessage();}}
    private void skills(){int x=6,w=primary.getWidth()-12,columns=w>=540?3:w>=300?2:1,cw=(w-(columns-1)*8)/columns,y=7;var saves=ProficiencyModel.checks(character,true);var skills=ProficiencyModel.checks(character,false);primary.label("Gold: trained · click a check for its breakdown",x,y,w,RpgTheme.MUTED);y+=20;for(int row=0;row<(6+columns-1)/columns;row++){int bottom=y;for(int col=0;col<columns;col++){int i=row*columns+col;if(i>=6)continue;String key=CreatorDraftState.ABILITIES.get(i);int gx=x+col*(cw+8),gy=y;primary.icon(key,gx,gy,20);primary.boldLabel(AbilityWorkspace.NAMES.get(key),gx+26,gy+5,cw-26,RpgTheme.GOLD);gy+=26;for(var c:saves)if(c.ability().equals(key)){check(c,"Save",gx,gy,cw);gy+=24;}for(var c:skills)if(c.ability().equals(key)){check(c,c.name(),gx,gy,cw);gy+=24;}bottom=Math.max(bottom,gy+9);}y=bottom;}var edit=primary.control("edit:choices",new RpgButton(x,y,w,19,"Edit proficiencies and expertise","",()->{if(fresh&&!busy&&editable())client.setScreen(new ProficiencyPickerScreen(this,character,source));}));edit.active=editable();y+=26;var scores=primary.control("edit:scores",new RpgButton(x,y,w,19,"Edit ability scores","",()->{if(!fresh||busy||!editable())return;if(source.library())client.setScreen(new AbilityScoreScreen(this,character));else client.setScreen(new dev.tacticalcombat.client.ServerCharactersScreen(this,null));}));scores.active=editable()&&text(character,"profile").equals("srd_5_1");y+=26;primary.wrapped("Check and saving-throw rolls are unavailable here. Use your DM's dice; these sheet choices do not change automated combat.",x,y,w,RpgTheme.MUTED);}
    private void check(DashboardModel.Check c,String label,int x,int y,int width){var entry=new FeatureReference.Entry("sheet:check:"+label+":"+c.name(),label.equals("Save")?c.name()+" saving throw":c.name(),"Character sheet",0,"","Tabletop check","","","",c.breakdown(),"INFORMATIONAL",c.breakdown());primary.control(entry.id(),new RpgButton(x,y,width,19,(label.equals("Save")?"Saving Throw":label)+" "+(ProficiencyModel.hasScores(character)?c.display():"—"),"",()->inspect(entry)).selected(c.proficient()).hint(entry.tooltip()+(c.expertise()?"\nExpertise":c.proficient()?"\nProficient":"\nNot proficient")));}
    private void background(){int x=7,w=primary.getWidth()-14,y=7;var identity=section("identity");for(String key:List.of("appearance","biography","personality","ideals","bonds","flaws")){String value=text(identity,key).isBlank()?"Not added yet":text(identity,key);int lines=textRenderer.getTextHandler().wrapLines(value,w-16,net.minecraft.text.Style.EMPTY).size(),h=Math.max(43,lines*12+30);primary.panel(label(key),x,y,w,h);primary.wrapped(value,x+8,y+25,w-16,RpgTheme.TEXT);y+=h+8;}var edit=primary.control("edit:story",new RpgButton(x,y,w,19,"Edit character background","",()->{if(fresh&&!busy&&editable())client.setScreen(new CharacterDetailsScreen(this,character,source));}));edit.active=editable();}
    private JsonObject section(String key){return SheetSections.read(character.getAsJsonObject("sheet"),key);}
    private String restriction(){return DashboardModel.restriction(character,source.library(),self(),combat());}
    private boolean trackable(){return trackable("trackers");}
    private boolean trackable(String section){return character!=null&&(source.library()?editable():flag(character,"canTrack")&&character.has("manualRevision")&&array(character,"manualSections").asList().stream().anyMatch(e->e.getAsString().equals(section)));}
    private String trackerRestriction(){return "Your control and campaign policy must allow this change.";}
    private void inventory(){var body=listBounds();boolean stacked=body.width()<380;int left=stacked?body.width():(body.width()-10)/2,h=stacked?Math.max(50,(body.height()-6)/2):body.height(),sx=stacked?body.x():body.x()+left+10,sy=stacked?body.y()+h+6:body.y(),sw=stacked?body.width():body.width()-left-10,sh=stacked?Math.max(24,body.height()-h-6):body.height();int bw=(left-9)/4;for(var category:InventoryModel.Category.values()){var b=button(category.name().charAt(0)+category.name().substring(1).toLowerCase(Locale.ROOT),"",body.x()+category.ordinal()*(bw+3),body.y(),bw,18,()->{inventoryCategory=category;display();});b.selected(inventoryCategory==category);inventoryControls.add(b);}int aw=(left-4)/2;inventoryControls.add(button("Add from Catalog","",body.x(),body.y()+22,aw,18,()->{if(money.dirty()){message="Save currency first.";return;}if(fresh&&!busy&&editable())client.setScreen(InventoryForms.catalog(this,character,source));}).hint("Add from Catalog"));inventoryControls.add(button("Add Custom Item","",body.x()+aw+4,body.y()+22,aw,18,()->{if(money.dirty()){message="Save currency first.";return;}if(fresh&&!busy&&editable())client.setScreen(InventoryForms.item(this,character,source,null));}).hint("Add Custom Item"));filterInput.setDimensionsAndPosition(left,18,body.x(),body.y()+44);list.setDimensionsAndPosition(left,Math.max(18,h-66),body.x(),body.y()+66);var entries=InventoryModel.entries(section("inventory"),inventoryCategory,query);for(var e:entries)row(e.label(),e.quantity()+" × · "+(e.equipped()?"Equipped":"Carried")+" · "+e.category().toLowerCase(Locale.ROOT),true,"",()->{inventorySelection=e.id();display();});if(entries.stream().noneMatch(e->e.id().equals(inventorySelection)))inventorySelection=entries.isEmpty()?"":entries.getFirst().id();primary=addDrawableChild(new CharacterCanvas(new UiLayout.Rect(sx,sy,sw,sh)));String id=inventorySelection;money.controls(primary,textRenderer,6,fresh&&!busy&&editable(),this::saveCurrency);InventoryDetails.build(primary,InventoryModel.find(section("inventory"),id),new InventoryDetails.Actions(){public boolean editable(){return fresh&&!busy&&CharacterDashboardScreen.this.editable();}public void quantity(int delta){editInventory(id,delta,false);}public void equip(){editInventory(id,0,true);}public void edit(){if(fresh&&!busy&&editable())client.setScreen(InventoryForms.item(CharacterDashboardScreen.this,character,source,InventoryModel.find(section("inventory"),id)));}public void remove(){if(!fresh||busy||!editable())return;confirm("Remove equipment?","Remove this sheet entry only; physical Minecraft inventory stays unchanged.",()->saveInventory(InventoryModel.remove(section("inventory"),id)));}},104);primary.position(positions.getOrDefault(tab,0));filter();int selectedIndex=0;for(int i=0;i<entries.size();i++)if(entries.get(i).id().equals(inventorySelection))selectedIndex=i;list.restorePosition(list.firstVisible(),selectedIndex);}
    private InventoryModel.Category inventoryCategory=InventoryModel.Category.ALL;
    private void editInventory(String id,int delta,boolean equip){if(!fresh||busy||!editable())return;Runnable action=()->{if(!fresh||busy||!editable())return;saveInventory(equip?InventoryModel.equipped(section("inventory"),id):InventoryModel.quantity(section("inventory"),id,delta));};if(!source.library()&&flag(character,"approved"))confirm("Change equipment?","This edit may need DM approval again.",action);else action.run();}
    private void saveInventory(JsonObject data){if(!fresh||busy||!editable())return;mutate(source.edit(),source.sectionArgs(character,"inventory",data),next->{character=SnapshotReplies.checked(source,next);display();});}
    private void saveCurrency(){if(!fresh||busy||!editable())return;if(money.conflict()){confirm("Review changed currency?","Server money changed. Replace it with these retained entries?",()->{money.reviewed();saveCurrency();});return;}try{var sent=Map.copyOf(money.values);var data=money.data(section("inventory"));mutate(source.edit(),source.sectionArgs(character,"inventory",data),next->{character=SnapshotReplies.checked(source,next);money.accept(section("inventory"),sent);display();});}catch(RuntimeException invalid){message=invalid.getMessage();}}
    @Override public void close(){if(busy)return;if(money!=null&&money.dirty())confirm("Discard unsaved currency?","Saved money is unchanged.",()->client.setScreen(parent));else super.close();}
    private void features(){JsonObject f=section("features");var entries=new ArrayList<JsonObject>();for(var e:f.getAsJsonArray("entries"))entries.add(e.getAsJsonObject());entries.sort(Comparator.comparing(o->text(o,"kind")+text(o,"source")+text(o,"name")));for(var e:entries){String uses=e.has("uses")&&!e.get("uses").isJsonNull()?" · usage pool recorded":"";row(text(e,"name"),text(e,"kind")+" · "+text(e,"source")+" · "+text(e,"status")+uses+" · "+shorten(text(e,"description")),true,"",()->{client.setScreen(new FeatureInspectScreen(this,FeatureReference.recorded(e)));});}for(var e:f.getAsJsonArray("resources")){var p=e.getAsJsonObject();valueTracker(text(p,"name"),RpgRecords.Action.RESOURCE,"features",text(p,"id"),0,p.get("current").getAsInt(),p.get("maximum").getAsInt(),trackable("features")&&text(p,"status").equals("MANUAL"));}row("Edit features","Feature effects do not run automatically",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"features",source)));}
    private void spells(){JsonObject b=section("spellbook");info("Spellcasting summary",text(b,"recordedAbility")+" · save DC "+text(b,"recordedSaveDc")+" · attack "+text(b,"recordedAttackModifier")+" · sheet values");row("Level filter",spellLevel<0?"All spell levels":spellLevel==0?"Cantrips":"Level "+spellLevel,true,"",()->client.setScreen(new ChoiceScreen(this,"Spell level filter",java.util.stream.IntStream.rangeClosed(-1,9).mapToObj(Integer::toString).toList(),v->Integer.parseInt(v)<0?"All":Integer.parseInt(v)==0?"Cantrips":"Level "+v,v->{spellLevel=Integer.parseInt(v);display();})));var selections=new ArrayList<JsonObject>();for(var e:b.getAsJsonArray("selections"))selections.add(e.getAsJsonObject());selections.sort(Comparator.<JsonObject>comparingInt(s->{var d=definition(b,text(s,"spell"));return d==null?99:d.get("level").getAsInt();}).thenComparing(s->{var d=definition(b,text(s,"spell"));return d==null?text(s,"spell"):text(d,"name");}));for(var s:selections){var d=definition(b,text(s,"spell"));if(d!=null&&spellLevel>=0&&d.get("level").getAsInt()!=spellLevel)continue;String name=d==null?text(s,"spell"):text(d,"name");String detail=d==null?"Definition unavailable":((d.get("level").getAsInt()==0?"Cantrip":"Level "+d.get("level").getAsInt())+" · "+text(d,"school")+" · "+(flag(s,"alwaysPrepared")?"always prepared":flag(s,"prepared")?"prepared":flag(s,"known")?"known":"recorded")+" · "+text(d,"castingTime")+" · "+text(d,"range"));row(name,detail,true,"",()->{client.setScreen(new FeatureInspectScreen(this,SpellReference.entry(d,s)));});}int i=0;for(var e:b.getAsJsonArray("slots")){var s=e.getAsJsonObject();valueTracker("Level "+s.get("level").getAsInt()+" spell slots",RpgRecords.Action.SPELL_SLOT,"spellbook","",i++,s.get("current").getAsInt(),s.get("maximum").getAsInt(),trackable("spellbook"));}info("Standard catalog","Empty and explicitly unavailable; custom definitions only. No Cast Spell action exists.");row("Edit spellbook","Add spells and choose preparation; casting is unavailable",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"spellbook",source)));}
    private void manual(RpgRecords.Change change){if(!trackable(change.section())){message=trackerRestriction();return;}mutate(source.manualOperation(),source.manualArgs(character,change),data->{character=SnapshotReplies.checked(source,data);display();});}
    private void chooseTracker(String name,RpgRecords.Action action,int value,int max,boolean enabled){row(name,Integer.toString(value)+" · manual tracker",enabled,trackerRestriction(),()->client.setScreen(new ChoiceScreen(this,name,java.util.stream.IntStream.rangeClosed(0,max).mapToObj(Integer::toString).toList(),v->v,v->manual(new RpgRecords.Change(action,"trackers","",0,Integer.parseInt(v))))));}
    private void valueTracker(String name,RpgRecords.Action action,String section,String key,int index,int value,int max,boolean enabled){row(name,value+" / "+max+" · manual resource",enabled,trackerRestriction(),()->{var field=List.of(new RecordFormScreen.Field("value","Current (0–"+max+")",Integer.toString(value),5));client.setScreen(new RecordFormScreen(this,name,source.read(),source.readArgs(),field,(state,v)->source.manualArgs(state,new RpgRecords.Change(action,section,key,index,WizardEditors.integer(v,"value",0,max))),source.manualOperation(),data->client.setScreen(this),"Server-confirmed inert bookkeeping; does not heal, recover resources automatically, or change combat.").expected(character));});}
    private static String join(JsonObject o,String key){var v=new ArrayList<String>();for(var e:array(o,key))v.add(e.getAsString());return v.isEmpty()?"None":String.join(", ",v);}
    private static JsonObject definition(JsonObject b,String id){for(var e:b.getAsJsonArray("customDefinitions")){var d=e.getAsJsonObject();if(text(d,"id").equals(id))return d;}return null;}
    private static String label(String key){return switch(key){case "characterClass"->"Class";default->Character.toUpperCase(key.charAt(0))+key.substring(1);};}
    private static String shorten(String value){return value.length()>140?value.substring(0,137)+"…":value;}
    @Override protected void request(UiApiService.Operation op,JsonObject args,java.util.function.Consumer<UiApiService.Reply> callback){super.request(op,args,r->{if(!r.code().equals("OK")&&!r.code().equals("RATE_LIMIT")){fresh=false;if(r.code().equals("FORBIDDEN")||r.code().equals("NOT_FOUND")||r.code().equals("UNAUTHORIZED")){character=null;encounter=new JsonObject();if(primary!=null){remove(primary);primary=null;}inventoryControls.forEach(this::remove);inventoryControls.clear();clearRows();if(list!=null)list.rows(List.of());}}callback.accept(r);});}
    @Override protected void content(DrawContext g,int mx,int my,float delta){if(character==null)return;var s=DashboardLayout.shell(frame).summary();RpgTheme.panel(g,s.x(),s.y(),s.width(),s.height(),RpgTheme.PANEL,false);String identity=text(character,"name")+"\nLevel "+DashboardModel.xp(character.getAsJsonObject("sheet")).level()+"\n"+text(section("identity"),"species")+"\n"+text(section("identity"),"characterClass")+"\n"+campaignName+"\n"+DashboardModel.header(character,source.library(),selected(),combat());if(DashboardLayout.shell(frame).compactSummary())RpgTheme.text(g,textRenderer,source.library()?"Personal library":campaignName+(flag(character,"approved")?" · approved":" · needs approval"),s.x()+5,s.y()+(s.height()-9)/2,s.width()-10,RpgTheme.GOLD);else{if(client.player!=null&&(source.library()||text(character,"owner").equals(self())))PlayerSkinDrawer.draw(g,client.player.getSkinTextures(),s.x()+s.width()/2-12,s.y()+8,24);paragraphs(g,identity,s.x()+6,s.y()+38,s.width()-12,s.height()-44);}}
}
